func.func @main(%x: tensor<12xf32>) -> tensor<6xf32> {
  %start = constant 1 : i64
  %limit = constant 12 : i64
  %stride = constant 2 : i64
  %start_indices = array<i64: 0> : array<i64>
  %limit_indices = array<i64: 6> : array<i64>
  %strides = array<i64: 1, 2, 3, 4, 5, 6> : array<i64>  // placeholder, will set proper strides below

  // Since we want to slice from index 1 to 12 with step 2, for each output element i:
  // start index = 1 + 2 * i
  // For i in 0..5, start indices are 1, 3, 5, 7, 9, 11
  // limit indices are start + 1 (since we want to take one element per step)
  // But in StableHLO, slice's start_indices and limit_indices are fixed per dimension.
  // To implement x[1:12:2], we can perform a single slice with start=1, limit=12, stride=2.

  // So, set:
  %slice_start_indices = array<i64: 1> : array<i64>
  %slice_limit_indices = array<i64: 12> : array<i64>
  %slice_strides = array<i64: 2> : array<i64>

  %result = "stablehlo.slice"(%x) {
    start_indices = %slice_start_indices,
    limit_indices = %slice_limit_indices,
    strides = %slice_strides
  } : (tensor<12xf32>) -> tensor<6xf32>

  return %result : tensor<6xf32>
}
