// StableHLO program implementing softmax over dimension 1
func.func @main(%x: tensor<4x8xf32>) -> tensor<4x8xf32> {
  // Step 1: Compute exp(x)
  %exp_x = "stablehlo.exponential"(%x) : (tensor<4x8xf32>) -> tensor<4x8xf32>

  // Step 2: Compute sum_k exp(x[i, k]) for each row i
  // Initialize sum with zeros
  %zero = "stablehlo.constant"() {value = dense<0x00000000> : tensor<f32>} : () -> tensor<f32>
  // Reduce over dimension 1 (columns)
  %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<4x8xf32>, tensor<f32>) -> tensor<4xf32>

  // Step 3: Broadcast sum to shape of x for division
  // The sum has shape [4], need to broadcast to [4,8]
  %broadcast_dims = array<i64: 1> // broadcast along dimension 1
  %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = %broadcast_dims} : (tensor<4xf32>) -> tensor<4x8xf32>

  // Step 4: Compute softmax numerator: exp(x)
  // Already computed as %exp_x

  // Step 5: Divide exp(x) by sum
  %softmax = "stablehlo.divide"(%exp_x, %sum_broadcast) : (tensor<4x8xf32>, tensor<4x8xf32>) -> tensor<4x8xf32>

  return %softmax : tensor<4x8xf32>
}
