// StableHLO program implementing the forward pass of the described model
module {
  func.func @main(%arg0: tensor<f32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Step 1: Perform matrix multiplication: x = linear(%arg3, %arg1, %arg2)
    // linear: y = matmul(%arg3, %arg1) + %arg2
    %matmul = "stablehlo.dot_general"(%arg3, %arg1) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [],
                                              lhs_contracting_dimensions = [1],
                                              rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: y = matmul + bias
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %x = "stablehlo.add"(%matmul, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 2: Compute minimum with constant (constant = 2.0)
    // Create constant tensor with shape <7> filled with 2.0
    %const_value = "stablehlo.constant"() {value = dense<2.0> } : () -> tensor<f32>
    // Broadcast constant to shape <6x7>
    %const_broadcast = "stablehlo.broadcast_in_dim"(%const_value) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<f32>) -> tensor<6x7xf32>
    // Compute min
    %min_x_const = "stablehlo.minimum"(%x, %const_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Subtract the constant from the min result
    %result = "stablehlo.subtract"(%min_x_const, %const_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return the final tensor
    return %result : tensor<6x7xf32>
  }
}
