func.func @main(%idx: tensor<5xi32>) -> tensor<5x8xf32> {
  %c0 = constant dense<0> : tensor<i32>
  %c8 = constant dense<8> : tensor<i32>
  %one = constant dense<1.0 : f32> : tensor<f32>
  %zero = constant dense<0.0 : f32> : tensor<f32>

  // Generate a tensor of shape <8> with values [0, 1, 2, 3, 4, 5, 6, 7]
  %iota_dim0 = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx to shape <5x8>
  %bcast_idx = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Expand iota to shape <5x8> for comparison
  %bcast_iota = "stablehlo.broadcast_in_dim"(%iota_dim0) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<1x8xi32>
  %bcast_iota_reshaped = "stablehlo.broadcast_in_dim"(%bcast_iota) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<1x8xi32>) -> tensor<5x8xi32>

  // Compare idx with each value in [0..7]
  %cmp = "stablehlo.compare"(%bcast_idx, %bcast_iota_reshaped) {
    comparison_direction = #stablehlo<LT>,
    compare_type = #stablehlo<SIGNED>
  } : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // For each position, check if idx[n] == c
  %eq = "stablehlo.compare"(%bcast_idx, %bcast_iota_reshaped) {
    comparison_direction = #stablehlo<EQ>,
    compare_type = #stablehlo<SIGNED>
  } : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Select 1.0 where equal, else 0.0
  %result = "stablehlo.select"(%eq, %one, %zero) : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  return %result : tensor<5x8xf32>
}
