    %rhs_dilation = array<i64: 1, 1, 1> : tensor<3xi64>
    // dimension_numbers: input and output dims: [b, f, 0, 1, 2], kernel dims: [o, i, 0, 1, 2]
    #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]> = {
      batch_dimension = 0,
      feature_dimension = 1,
      spatial_dimensions = [2, 3, 4]
    }

    %result = "stablehlo.convolution"(%arg1, %arg0) {
      window_strides = %window_strides,
      padding = %padding,
      lhs_dilation = %lhs_dilation,
      rhs_dilation = %rhs_dilation,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<8x3x16x7x7xf32>, tensor<6x3x3x5x7xf32>) -> tensor<8x6x14x3x1xf32>

    return %result : tensor<8x6x14x3x1xf32>
