  // Convert column indices to float
  %cols_f = "stablehlo.convert"(%cols) {to_element_type = f32} : (tensor<3x3xi32>) -> tensor<3x3xf32>
  // Compare: j <= i (column index <= row index)
  %cmp = "stablehlo.compare"(%cols_f, %rows_f) {
    comparison_direction = #stablehlo<LE>,
    compare_type = #stablehlo<SIGNED>
  } : (tensor<3x3xf32>, tensor<3x3xf32>) -> tensor<3x3xi1>
  // Select elements: if true, take x; else 0.0
