// StableHLO program implementing the forward pass of the described PyTorch model
// with inputs: %arg0 (matmul weight), %arg1 (bias), %arg2 (input tensor)
// Output: tensor<16xf32> (max pooled, GELU activated, scaled, reduced over features)

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16x16xf32>) -> tensor<16xf32> {
  // Step 1: matmul = %matmul_result = matmul(%arg2, transpose(%arg0))
  // Transpose %arg0 to get shape (16,16) -> (16,16) (since square, transpose is same shape)
  %transposed_weight = "stablehlo.transpose"(%arg0) {permutation = [1, 0]} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Perform matmul: %matmul = dot_general(%arg2, %transposed_weight)
  %matmul = "stablehlo.dot_general"(%arg2, %transposed_weight) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: average pooling over features (dim=1)
  // Expand dims to (batch, features) -> (batch, features)
  // For AvgPool1d, input shape: (batch, channels)
  // Input shape is (16,16), so apply AvgPool1d with kernel size 16
  %avg_pool = "stablehlo.avg_pool"(%matmul) {
    window_dimensions = [16],
    window_strides = [16],
    padding = dense<[[0, 0]]> : tensor<1x2xi64>
  } : (tensor<16x16xf32>) -> tensor<16x1xf32>
  // Squeeze to (16)
  %avg_pool_squeezed = "stablehlo.reshape"(%avg_pool) : (tensor<16x1xf32>) -> tensor<16xf32>

  // Step 3: GELU activation
  // GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = "stablehlo.constant"() {value = dense<0x3FF6A09E66FAAC18> } : () -> tensor<f32> // 1.4142135
  %x_div_sqrt2 = "stablehlo.divide"(%avg_pool_squeezed, %sqrt2) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // erf(x / sqrt(2))
  %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<16xf32>) -> tensor<16xf32>
  // 1 + erf(...)
  %one = "stablehlo.constant"() {value = dense<1.0> } : () -> tensor<f32>
  %one_plus_erf = "stablehlo.add"(%one, %erf_x) : (tensor<f32>, tensor<f32>) -> tensor<16xf32>
  // 0.5 * x
  %half = "stablehlo.constant"() {value = dense<0.5> } : () -> tensor<f32>
  %x_times_half = "stablehlo.multiply"(%avg_pool_squeezed, %half) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // GELU output: 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = "stablehlo.multiply"(%x_times_half, %one_plus_erf) : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>

  // Step 4: scale by scale_factor (2.0)
  %scale_factor = "stablehlo.constant"() {value = dense<2.0> } : () -> tensor<f32>
  %scaled = "stablehlo.multiply"(%gelu, %scale_factor) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // Step 5: max over features (dim=1)
  // Reduce max over axis 0 (features)
  %init_max = "stablehlo.constant"() {value = dense< -3.4028235e38 > } : () -> tensor<f32> // min float
  %max_result = "stablehlo.reduce"(%scaled, %init_max) {
    dimensions = [1]
  } : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // The reduce reduces over features, resulting in shape (batch=16)

  // Output is tensor<16xf32>
  return %max_result : tensor<16xf32>
}
