module {
  func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
    // Step 1: Compute the Frobenius norm of the input tensor
    // torch.norm with p='fro' computes the Frobenius norm, which is equivalent to the L2 norm over all elements
    // in the tensor, i.e., sqrt(sum of squares of all elements).

    // 1.1: Compute element-wise square: x^2
    %x_squared = "stablehlo.multiply" %arg0, %arg0 : tensor<6x7x8x8xf32>

    // 1.2: Reduce sum over all elements to get sum of squares
    // The reduction is over all dimensions: 0,1,2,3
    // Create a constant for the dimensions to reduce over
    %dims = "stablehlo.constant"() {value = dense<[0, 1, 2, 3]> : tensor<4xi64>} : () -> tensor<4xi64>

    // Initialize the reduction with 0.0
    %zero = "stablehlo.constant"() {value = dense<0x00000000> : tensor<f32>} : () -> tensor<f32>

    // 1.3: Perform reduce sum over all dimensions
    %sum_of_squares = "stablehlo.reduce"(%x_squared, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %s : (tensor<f32>) -> ()
    }) {dimensions = dense<[0, 1, 2, 3]>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<f32>

    // 1.4: Compute sqrt of sum to get Frobenius norm
    %norm = "stablehlo.sqrt" %sum_of_squares : tensor<f32>

    // 2: Broadcast norm to the shape of input tensor for division
    // The norm is scalar, need to broadcast to shape [6,7,8,8]
    // broadcast_in_dim with broadcast_dimensions = [0,1,2,3]
    %broadcast_dims = "stablehlo.constant"() {value = dense<[0, 1, 2, 3]> : tensor<4xi64>} : () -> tensor<4xi64>
    %norm_broadcast = "stablehlo.broadcast_in_dim" %norm {broadcast_dimensions = dense<[0, 1, 2, 3]>} : (tensor<f32>) -> tensor<6x7x8x8xf32>

    // 3: Divide input tensor by the broadcasted norm
    %output = "stablehlo.divide" %arg0, %norm_broadcast : tensor<6x7x8x8xf32>, tensor<6x7x8x8xf32>

    // Return the normalized tensor
    return %output : tensor<6x7x8x8xf32>
  }
}
