// StableHLO program implementing a forward pass of a model applying SELU activation
// on input tensor of shape 6x7, in training mode, using batch statistics.
// The operation is simply applying the SELU activation function element-wise.

func.func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Constants for SELU parameters
  %alpha = "stablehlo.constant"() {value = dense<1.6732632423543772> : tensor<f32>} : () -> tensor<f32>
  %scale = "stablehlo.constant"() {value = dense<1.0507009873554805> : tensor<f32>} : () -> tensor<f32>

  // Compute scaled input: %scaled_input = %arg0 * %scale
  %scaled_input = "stablehlo.multiply" %arg0, %scale : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute exponential of scaled input: %exp_scaled_input = exp(%scaled_input)
  %exp_scaled_input = "stablehlo.exponential" %scaled_input : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute exponential of negative scaled input: %exp_neg_scaled_input = exp(-%scaled_input)
  %neg_scaled_input = "stablehlo.negate" %scaled_input : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %exp_neg_scaled_input = "stablehlo.exponential" %neg_scaled_input : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute denominator: 1 + exp(-scaled_input)
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %denominator = "stablehlo.add" %one, %exp_neg_scaled_input : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute logistic: 1 / (1 + exp(-scaled_input))
  %logistic = "stablehlo.divide" %one, %denominator : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute scaled logistic: scale * logistic
  %scaled_logistic = "stablehlo.multiply" %logistic, %scale : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute scaled input: scale * scaled_input
  // (already computed as %scaled_input, but for clarity, reuse)
  // Now compute the SELU output: scale * (x if x > 0 else alpha * (exp(x) - 1))
  // But since SELU is defined as: scale * (x if x > 0 else alpha * (exp(x) - 1))
  // We need to compute the positive part and the negative part separately.

  // Compute relu: max(%arg0, 0)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %relu = "stablehlo.maximum" %arg0, %zero : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute exp(%arg0)
  %exp_arg0 = "stablehlo.exponential" %arg0 : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute exp(%arg0) - 1
  %exp_minus_one = "stablehlo.subtract" %exp_arg0, %one : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute negative part: alpha * (exp(x) - 1)
  %alpha_times_exp_minus_one = "stablehlo.multiply" %alpha, %exp_minus_one : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute positive part: relu
  // Compute negative part: min(%arg0, 0) = %arg0 - relu(%arg0)
  %neg_part = "stablehlo.subtract" %arg0, %relu : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute negative part scaled by alpha: alpha * min(x, 0)
  // Actually, for SELU, negative part is alpha * (exp(x) - 1), but for x <= 0, the formula is alpha * (exp(x) - 1)
  // For x > 0, it's just x.
  // So, combine positive and negative parts:
  // output = scale * (x if x > 0 else alpha * (exp(x) - 1))

  // Create a mask for x > 0
  %x_gt_zero_mask = "stablehlo.compare" %arg0, %zero {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<compare_type FLOAT>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xi1>

  // Select positive part where mask is true, negative part where false
  %sel_pos = "stablehlo.select" %x_gt_zero_mask, %arg0, %alpha_times_exp_minus_one : (tensor<6x7xi1>, tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Final output: scale * selected
  %output = "stablehlo.multiply" %scale, %sel_pos : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %output : tensor<6x7xf32>
}
