module {
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
    // Step 1: Compute linear(x) = matmul(%arg2, %arg0^T) + %arg1
    // Transpose %arg0 to get shape (7x7)
    %arg0_T = "stablehlo.transpose"(%arg0) {permutation = [1, 0]} : tensor<7x7xf32> // shape (7x7)
    // Perform dot_general: %matmul = %arg2 (6x7) x %arg0_T (7x7) -> (6x7)
    %dot = "stablehlo.dot_general"(%arg2, %arg0_T) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [],
                                              lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: %bias_broadcasted = broadcast %arg1 to shape (6x7)
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = [0]
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // Add bias to matmul result
    %linear_out = "stablehlo.add"(%dot, %bias_broadcasted) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Step 2: Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
    // Compute -x
    %neg_linear_out = "stablehlo.negate"(%linear_out) : tensor<6x7xf32>
    // Compute exp(-x)
    %exp_neg = "stablehlo.exponential"(%neg_linear_out) : tensor<6x7xf32>
    // Compute 1 + exp(-x)
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %one_broadcast = "stablehlo.broadcast_in_dim"(%one_const) {
