    %denominator = "stablehlo.add"(%one_broadcast, %exp_neg) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute sigmoid: 1 / (1 + exp(-x))
    %sigmoid = "stablehlo.divide"(%one_broadcast, %denominator) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Step 3: Sum over dim=1 (columns), keepdim=True -> shape (6x1)
    // Prepare reduction init: scalar 0.0
