// StableHLO program implementing a 2D Average Pooling operation as described.
// The input tensor shape: [16, 16, 16, 16], output shape: [16, 16, 1, 1].

func.func @main(%arg0: tensor<16x16x16x16xf32>) -> tensor<16x16x1x1xf32> {
  // Step 1: Define constants for kernel size, stride, and padding.
  %kernel_size = "stablehlo.constant"() {value = dense<11> : tensor<i64>} : () -> tensor<i64>
  %stride = "stablehlo.constant"() {value = dense<11> : tensor<i64>} : () -> tensor<i64>
  %padding = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>

  // Step 2: Compute the shape of the input tensor.
  // Extract dimensions: batch, channels, height, width.
  // Since shape is static, we can directly use constants.
  // Alternatively, use shape operations if dynamic shapes are needed.
  // Here, shapes are known at compile time.

  // Step 3: Compute the output spatial dimensions after pooling.
  // Formula:
  // output_size = floor((input_size + 2*padding - kernel_size) / stride) + 1
  // For height and width (both 16):
  %input_height = dense<16> : tensor<i64>
  %input_width = dense<16> : tensor<i64>

  // Compute numerator for height
  %two_padding_h = "stablehlo.multiply"(%padding, %dense<2> : tensor<i64>) : (tensor<i64>) -> tensor<i64>
  %numerator_h = "stablehlo.subtract"(
    "stablehlo.add"(%input_height, %two_padding_h) : (tensor<i64>, tensor<i64>) -> tensor<i64>,
    %kernel_size
  ) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  // Compute height output size
  %height_div = "stablehlo.divide"(%numerator_h, %stride) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %height_floor = "stablehlo.floor"(%height_div) : (tensor<f32>) -> tensor<i32>
  // Convert to i64
  %height_output = "stablehlo.cast"(%height_floor) {to = tensor<i64>} : (tensor<f32>) -> tensor<i64>
  // Add 1
  %height_output_plus_one = "stablehlo.add"(%height_output, dense<1> : tensor<i64>) : (tensor<i64>, tensor<i64>) -> tensor<i64>

  // Similarly for width
  %numerator_w = "stablehlo.subtract"(
    "stablehlo.add"(%input_width, %two_padding_h) : (tensor<i64>, tensor<i64>) -> tensor<i64>,
    %kernel_size
  ) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %width_div = "stablehlo.divide"(%numerator_w, %stride) : (tensor<i64>, tensor<i64>) -> tensor<i64>
  %width_floor = "stablehlo.floor"(%width_div) : (tensor<f32>) -> tensor<i32>
  %width_output = "stablehlo.cast"(%width_floor) {to = tensor<i64>} : (tensor<f32>) -> tensor<i64>
  %width_output_plus_one = "stablehlo.add"(%width_output, dense<1> : tensor<i64>) : (tensor<i64>, tensor<i64>) -> tensor<i64>

  // Step 4: Reshape input tensor to 4D if needed (already 4D).
  // Input shape: [16, 16, 16, 16], no reshape needed.

  // Step 5: Define window dimensions, strides, and padding for reduce_window.
  // Window dimensions: [1, 1, kernel_size, kernel_size]
  %window_dims = "stablehlo.constant"() {value = dense<[1, 1, 11, 11]> : tensor<4xi64>} : () -> tensor<4xi64>
  // Strides: [1, 1, stride, stride]
  %window_strides = "stablehlo.constant"() {value = dense<[1, 1, 11, 11]> : tensor<4xi64>} : () -> tensor<4xi64>
  // Padding: [ [0,0], [0,0], [0,0], [0,0] ] (no padding)
  %padding_tensor = "stablehlo.constant"() {value = dense<[[0,0],[0,0],[0,0],[0,0]]> : tensor<4x2xi64>} : () -> tensor<4x2xi64>

  // Step 6: Initialize the reduction value (average pooling).
  // For average pooling, sum over window and divide by window size.
  // But reduce_window performs reduction with a specified body.
  // We'll perform sum reduction and then divide.

  // Step 7: Define the reduction body: sum of two tensors.
  ^bb0(%a: tensor<f32>, %b: tensor<f32>): (tensor<f32>) {
    %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }

  // Step 8: Perform reduce_window with sum operation.
  %sum_result = "stablehlo.reduce_window"(%arg0, %constant_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): (tensor<f32>) {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  }) {window_dimensions = %window_dims, window_strides = %window_strides, padding = %padding_tensor} : (tensor<16x16x16x16xf32>, tensor<f32>) -> tensor<16x16x16x16xf32>

  // Step 9: Compute the total number of elements in each pooling window for division.
  // Window size: 11 * 11 = 121
  %window_size = "stablehlo.constant"() {value = dense<121> : tensor<i64>} : () -> tensor<i64>

  // Step 10: Divide sum by window size to get average.
  %avg = "stablehlo.divide"(%sum_result, "stablehlo.broadcast_in_dim"(%window_size) {broadcast_dimensions = [0]} : (tensor<i64>) -> tensor<16x16x16x16xf32>) : (tensor<16x16x16x16xf32>, tensor<16x16x16x16xf32>) -> tensor<16x16x16x16xf32>

  // Step 11: Slice the output to the computed spatial dimensions.
  // The output shape is [16, 16, 1, 1], so we slice height and width to size 1.
  // For simplicity, since the output shape is known, we can use "stablehlo.slice" with start indices 0 and sizes 1.
  %start_indices = "stablehlo.constant"() {value = dense<[0, 0, 0, 0]> : tensor<4i64>}
