    %diff = "stablehlo.subtract"(%scaled, %mean) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Sum squared differences
