    %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = %bcast_dims} : (tensor<7xf32>) -> tensor<6x7xf32>
    %scaled_bn = "stablehlo.multiply"(%normalized, %bn_weight_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %output = "stablehlo.add"(%scaled_bn, %bn_bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

