func.func @main(%x: tensor<4x3xf32>) -> tensor<4x3xf32> {
  %zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>
  %two = "stablehlo.constant"() {value = dense<2 : i64>} : () -> tensor<i64>
  %dim0 = "stablehlo.constant"() {value = dense<0 : i64>} : () -> tensor<i64>
  %dim1 = "stablehlo.constant"() {value = dense<1 : i64>} : () -> tensor<i64>
  %dim2 = "stablehlo.constant"() {value = dense<2 : i64>} : () -> tensor<i64>

  // Step 1: Square each element: x^2
  %x_squared = "stablehlo.multiply"(%x, %x) : (tensor<4x3xf32>, tensor<4x3xf32>) -> tensor<4x3xf32>

  // Step 2: Reduce sum over the last dimension (k) to get sum_k x[i,k]^2
  %sum_sq = "stablehlo.reduce"(%x_squared, %zero) ({
    ^bb0(%a: tensor<4x3xf32>, %b: tensor<4x3xf32>): %s = "stablehlo.add"(%a, %b) : (tensor<4x3xf32>, tensor<4x3xf32>) -> tensor<4x3xf32>
    "stablehlo.return"(%s) : (tensor<4x3xf32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<4x3xf32>, tensor<f32>) -> tensor<4x1xf32>

  // Step 3: Broadcast sum_k x[i,k]^2 to shape 4x3 for element-wise division
  %sum_sq_bcast = "stablehlo.broadcast_in_dim"(%sum_sq) {broadcast_dimensions = array<i64: 1>} : (tensor<4x1xf32>) -> tensor<4x3xf32>

  // Step 4: Compute sqrt of sum_k x[i,k]^2
  %norm = "stablehlo.sqrt"(%sum_sq_bcast) : (tensor<4x3xf32>) -> tensor<4x3xf32>

  // Step 5: Divide x by the norm to normalize
  %out = "stablehlo.divide"(%x, %norm) : (tensor<4x3xf32>, tensor<4x3xf32>) -> tensor<4x3xf32>

  return %out : tensor<4x3xf32>
