    // Compute scaled negative part: %neg_part = %arg0 * %slope
    %neg_part = "stablehlo.multiply"(%arg0, %slope) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // Compute positive part: %pos_part = "stablehlo.maximum"(%arg0, %zero)
    %pos_part = "stablehlo.maximum"(%arg0, %zero) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

