  // The target shape is [6,7,8]
  // The broadcast dims: [0, 1, 2]
  %broadcast_dims = array<i64: 0, 1, 2>
  %iota_broadcasted = "stablehlo.broadcast_in_dim"(%iota_reshaped) {broadcast_dimensions = %broadcast_dims} : (tensor<1x7x1xi64>) -> tensor<6x7x8xi64>

  // Step 3: For each position in the input, compare the input with the broadcasted iota tensor.
  // This will produce a boolean tensor indicating where input equals the index along dimension 1.
  %cmp = "stablehlo.compare"(%arg0, %iota_broadcasted) {comparison_direction = #stablehlo<LT>, compare_type = #stablehlo<SIGNED>} : (tensor<6x7x8xf32>, tensor<6x7x8xi64>) -> tensor<6x7x8xi1>

