// The input tensor shape: (6, 7, 8)
// The output tensor shape: (6, 7, 10)
// The weight tensor shape: (7, 7, 3) (matching in_channels, out_channels, kernel_size)

func.func @main(%arg0: tensor<7x7x3xf32>, %arg1: tensor<6x7x8xf32>) -> tensor<6x7x10xf32> {
  // Step 1: Reshape input from (6,7,8) to (6,8,7) for 1D convolution
  %perm_input = "stablehlo.transpose"(%arg1) {permutation = array<i64: 0, 2, 1>} : (tensor<6x7x8xf32>) -> tensor<6x8x7xf32>

  // Step 2: Prepare weight tensor for convolution
  // Original weight shape: (7,7,3)
  // For conv, shape: (out_channels, in_channels, kernel_size)
  // We need to flip the kernel for transposed convolution, so reverse along kernel dimension
  %weight_reversed = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2>} : (tensor<7x7x3xf32>) -> tensor<7x7x3xf32>

  // Step 3: Perform convolution
  // Convolution parameters:
  // window_strides = [1]
  // padding = [[1, 1]] (to match output size)
  // lhs_dilation = [1]
  // rhs_dilation = [1]
  // dimension_numbers: input (b, spatial, in_channels), kernel (out_channels, in_channels, kernel), output (b, spatial, out_channels)
  %conv_out = "stablehlo.convolution"(%perm_input, %weight_reversed) {
    window_strides = array<i64: 1>,
    padding = dense<[[1, 1]]> : tensor<1x2xi64>,
    lhs_dilation = array<i64: 1>,
    rhs_dilation = array<i64: 1>,
    dimension_numbers = #stablehlo.conv<[b, 0, 1]x[o, 1, 0]->[b, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x7xf32>, tensor<7x7x3xf32>) -> tensor<6x8x7xf32>

  // Step 4: Transpose back to (6,7,8)
  %conv_transposed = "stablehlo.transpose"(%conv_out) {permutation = array<i64: 0, 2, 1>} : (tensor<6x8x7xf32>) -> tensor<6x7x8xf32>

  // Step 5: Pad the output to get size 10 in the last dimension
  // Current size: 8, desired size: 10, so pad with 1 on both sides
  %pad_low = 0 : i64
  %pad_high = 2 : i64
  %padding_tensor = "stablehlo.concatenate"(%pad_low, %pad_high) {dimension = 0} : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %padding_attr = dense<[[1, 1]]> : tensor<1x2xi64>
  %padded = "stablehlo.pad"(%conv_transposed) {
    padding = %padding_attr,
    padding_value = 0.0 : f32
  } : (tensor<6x7x8xf32>) -> tensor<6x7x10xf32>

  // Return the final tensor
  return %padded : tensor<6x7x10xf32>
}
