                  %arg6: tensor<16x8x16x16xf32>) -> tensor<16x16x14x14xf32> {
    // Step 1: Convolution
    %conv = "stablehlo.convolution"(%arg6, %arg2) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>

    // Step 2: Add bias
    // %arg3 shape: (16,16), need to reshape bias to broadcast
    // Bias shape: (16, 1, 1), broadcast to (16, 1, 1, 1) to match convolution output
    %bias_reshaped = "stablehlo.reshape"(%arg3) : (tensor<16xf32>) -> tensor<16x1x1xf32>
    // Broadcast bias to match convolution output shape: (16, 1, 1, 1)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 0, 1, 2>
    } : (tensor<16x1x1xf32>) -> tensor<16x1x1x1xf32>
    // Expand bias to match convolution output shape (16, 16, 14, 14)
    %bias_bcast_expanded = "stablehlo.broadcast_in_dim"(%bias_bcast) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<16x1x1x1xf32>) -> tensor<16x16x14x14xf32>
    // Add bias
    %add_bias = "stablehlo.add"(%conv, %bias_bcast_expanded) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 3: Scale
    // %arg4 shape: (16), need to reshape to broadcast
    %scale_reshaped = "stablehlo.reshape"(%arg4) : (tensor<16xf32>) -> tensor<16x1x1xf32>
    // Broadcast scale to match shape
    %scale_bcast = "stablehlo.broadcast_in_dim"(%scale_reshaped) {
      broadcast_dimensions = array<i64: 0, 1, 2>
    } : (tensor<16x1x1xf32>) -> tensor<16x1x1x1xf32>
    // Expand scale
    %scale_bcast_expanded = "stablehlo.broadcast_in_dim"(%scale_bcast) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<16x1x1x1xf32>) -> tensor<16x16x14x14xf32>
    // Multiply
    %scaled = "stablehlo.multiply"(%add_bias, %scale_bcast_expanded) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 4: Sigmoid
    // Sigmoid = 1 / (1 + exp(-x))
    // Compute -x
