    // exp(-x)
    %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    // 1 constant
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    // Broadcast 1 to shape
    %one_bcast = "stablehlo.broadcast_in_dim"(%one_const) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<16x16x14x14xf32>
    // denominator: 1 + exp(-x)
    %denominator = "stablehlo.add"(%one_bcast, %exp_neg_x) : (tensor<16x16x14x14xf32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
