    } : (tensor<16x1x1x1xf32>) -> tensor<16x16x14x14xf32>
    // GroupNorm: (x - mean) / sqrt(variance + epsilon) * weight + bias
    // For simplicity, assume epsilon = 1e-5
    %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
