  %c_sqrt2 = "stablehlo.constant"() {value = dense<1.4142135623> : tensor<f32>} : () -> tensor<f32>
  %c_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Compute x / sqrt(2)
  %x_div_sqrt2 = "stablehlo.divide"(%arg0, %c_sqrt2) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute erf(x / sqrt(2))
  %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute 1 + erf(...)
  %one_plus_erf = "stablehlo.add"(%c_one, %erf_x) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute 0.5 * x
  %half_x = "stablehlo.multiply"(%c_half, %arg0) : (tensor<f32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = "stablehlo.multiply"(%half_x, %one_plus_erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %gelu : tensor<6x7xf32>
}
