// StableHLO program to normalize each row of a 7x3 tensor to unit L2 norm
module {
  func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
    // Step 1: Compute x^2 element-wise
    %x_squared = "stablehlo.multiply" %x, %x : tensor<7x3xf32>

    // Step 2: Reduce along dimension 1 (columns) to sum squares per row
    %init_zero = "stablehlo.constant"() {value = dense<0.0 : tensor<f32>} : () -> tensor<f32>
    %sum_squares = "stablehlo.reduce" %x_squared, %init_zero ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %s : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<7x3xf32>, tensor<f32>) -> tensor<7xf32>

    // Step 3: Broadcast sum to shape 7x3 for division
    %sum_broadcast_dims = array<i64: 1> // broadcast along dimension 1
    %sum_broadcast = "stablehlo.broadcast_in_dim" %sum_squares {broadcast_dimensions = %sum_broadcast_dims} : (tensor<7xf32>) -> tensor<7x3xf32>

    // Step 4: Compute sqrt of sum of squares
    %norm = "stablehlo.sqrt" %sum_broadcast : tensor<7x3xf32>

    // Step 5: Divide original x by norm to normalize
    %out = "stablehlo.divide" %x, %norm : tensor<7x3xf32>

    return %out : tensor<7x3xf32>
  }
}
