// StableHLO program to normalize each row of a 3x8 tensor to unit L2 norm
func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %two = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %eight = "stablehlo.constant"() {value = dense<8.0> : tensor<f32>} : () -> tensor<f32>

  // Step 1: Compute x^2 element-wise
  %x_squared = "stablehlo.multiply" %x, %x : tensor<3x8xf32>

  // Step 2: Sum over the last dimension (k=0..7) to get sum_k x[i,k]^2
  // reduce over dimension 1 (the last dimension)
  %sum_sq = "stablehlo.reduce" %x_squared, %zero ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add" %a, %b : tensor<f32>
      "stablehlo.return" %s : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3x8xf32>

  // Step 3: Reduce sum over last dimension to get a 3-element vector per row
  // Actually, sum over dimension 1 (columns), resulting in shape (3)
  // But reduce returns shape (3,). To keep consistent, we can reshape or broadcast later.
  // So, reduce over dimension 1, with initial zero
  %sum_sq_rows = "stablehlo.reduce" %sum_sq, %zero ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add" %a, %b : tensor<f32>
      "stablehlo.return" %s : (tensor<f32>)
  }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3xf32>

  // Step 4: Broadcast sum to shape (3,8) for division
  // broadcast sum over columns
  %bcast_sum = "stablehlo.broadcast_in_dim" %sum_sq_rows {broadcast_dimensions = array<i64: 1>} : (tensor<3xf32>) -> tensor<3x8xf32>

  // Step 5: Compute sqrt of sum for denominator
  %denominator = "stablehlo.sqrt" %bcast_sum : tensor<3x8xf32>

  // Step 6: Divide x by denominator element-wise
  %out = "stablehlo.divide" %x, %denominator : tensor<3x8xf32>

  return %out : tensor<3x8xf32>
}
