  %x_expanded = "stablehlo.broadcast_in_dim"(%x_bcast) {
    broadcast_dimensions = array<i64: 0, 1, 2>
  } : (tensor<2x1x5xf32>) -> tensor<2x3x5xf32>

  // Step 4: Expand y to shape [2, 3, 5]
  %y_expanded = "stablehlo.broadcast_in_dim"(%y_bcast) {
    broadcast_dimensions = array<i64: 0, 1, 2>
  } : (tensor<1x3x5xf32>) -> tensor<2x3x5xf32>

  // Step 5: Compute difference: diff = x_expanded - y_expanded
  %diff = "stablehlo.subtract"(%x_expanded, %y_expanded) : (tensor<2x3x5xf32>, tensor<2x3x5xf32>) -> tensor<2x3x5xf32>

