  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<2x3x5xf32>, tensor<2x3x5xf32>) -> tensor<2x3x5xf32>

  // Step 7: Reduce sum over the last dimension (d=2) to get shape [2,3]
  // Initialize with zero constant
