    dimensions = array<i64: 2>
  } : (tensor<2x3x5xf32>, tensor<f32>) -> tensor<2x3xf32>

  // The reduce outputs shape [2,3], but we need shape [2,3,1] to match output shape
  // Expand distances to shape [2,3,1]
  %distances_expanded = "stablehlo.broadcast_in_dim"(%distances) {
