// StableHLO program implementing the forward pass of the described model
// Arguments:
// %arg0: scale (tensor<7xf32>)
// %arg1: gemm.weight (tensor<7x7xf32>)
// %arg2: gemm.bias (tensor<7xf32>)
// %arg3: bn.weight (tensor<7xf32>)
// %arg4: bn.bias (tensor<7xf32>)
// %arg5: input (tensor<6x7xf32>)

// Result: tensor<6x7xf32>

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Step 1: matrix multiplication: x = input @ weight^T
  // Transpose weight to align dimensions for matmul
  %weight_T = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Perform dot_general: input (6x7), weight_T (7x7) -> (6x7)
  %matmul_result = "stablehlo.dot_general"(%arg5, %weight_T) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [],
                                           lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Step 2: Add bias: result + bias (broadcast bias over batch)
  // Broadcast bias to shape (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 0, 1>
  } : (tensor<7xf32>) -> tensor<6x7xf32>
  %biased = "stablehlo.add"(%matmul_result, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 3: Scale: multiply by scale parameter (broadcast over batch)
  // Expand scale to shape (7) -> (6x7)
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = "stablehlo.multiply"(%biased, %scale_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Step 4: Batch normalization
  // Compute mean and variance over batch (dimension 0)
  // For simplicity, approximate batch norm as: (x - mean) / sqrt(variance + epsilon) * gamma + beta
  // Since batch stats are used, compute mean over batch
  // Compute mean: reduce over dimension 0
  %dim0 = constant dense<0> : tensor<i64>
  %mean = "stablehlo.reduce"(%scaled, %arg4) {
    ^bb0(%a: tensor<6x7xf32>, %b: tensor<7xf32>): tensor<7xf32> {
      %sum = "stablehlo.add"(%a, %b) : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>
      "stablehlo.return"(%sum) : (tensor<6x7xf32>) -> ()
    }
  } {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // Divide sum by batch size (6) to get mean
  %batch_size = constant dense<6> : tensor<i64>
  %mean_div = "stablehlo.divide"(%mean, "stablehlo.convert"(%batch_size) : tensor<i64> -> tensor<f32>) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast mean to shape (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<7xf32>) -> tensor<6x7xf32>

  // Compute variance: reduce squared difference
  %diff = "stablehlo.subtract"(%scaled, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%diff_squared, constant dense<0.0 : f32>) {
    ^bb0(%a: tensor<6x7xf32>, %b: tensor<7xf32>): tensor<6x7xf32> {
      %sum = "stablehlo.add"(%a, "stablehlo.broadcast_in_dim"(%b) {broadcast_dimensions = array<i64: 0>}) : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>
      "stablehlo.return"(%sum) : (tensor<6x7xf32>) -> ()
    }
  } {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>
  // Divide by batch size to get variance
  %var = "stablehlo.divide"(%var_sum, "stablehlo.convert"(%batch_size) : tensor<i64> -> tensor<f32>) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Add epsilon to variance
  %epsilon = constant dense<0.00001 : f32>
  %var_eps = "stablehlo.add"(%var, %epsilon) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  // Compute sqrt of variance + epsilon
  %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Normalize: (x - mean) / stddev
  %x_centered = "stablehlo.subtract"(%scaled, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %x_norm = "stablehlo.divide"(%x_centered, %stddev) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Scale and shift: gamma (bn.weight), beta (bn.bias)
  // Broadcast gamma and beta
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {
    broadcast_dimensions = array<i64: 0>
  } : (tensor<7xf32>) -> tensor<6x7xf32>
  // Apply scale and shift
  %scaled_bn = "stablehlo.multiply"(%x_norm, %bn_weight_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %bn_output = "stablehlo.add"(%scaled_bn, %bn_bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Return final output
  return %bn_output : tensor<6x7xf32>
}
